<script setup>
import {computed,ref,watch} from 'vue'
import SimulationControls from './SimulationControls.vue'
import PropositionalCode from './PropositionalCode.vue'
import {hornExamples,validateHorn,traceHorn,forwardCode,sldCode} from '../services/propositional-inference.mjs'
const props=defineProps({initialMode:{type:String,default:'forward'}})
const mode=ref(props.initialMode),preset=ref('source'),custom=ref(null),step=ref(0),input=ref(''),error=ref('')
watch(preset,()=>{custom.value=null;input.value=JSON.stringify(hornExamples.find(e=>e.id===preset.value),null,2);error.value='';step.value=0},{immediate:true})
const example=computed(()=>custom.value||hornExamples.find(e=>e.id===preset.value)),validated=computed(()=>validateHorn(example.value)),frames=computed(()=>traceHorn(example.value,mode.value)),state=computed(()=>frames.value[Math.min(step.value,frames.value.length-1)])
const resetKey=computed(()=>JSON.stringify([example.value,mode.value]));watch(resetKey,()=>{step.value=0})
const status={start:'Khởi tạo hàng đợi từ các sự thực và số tiền đề còn chờ của mỗi luật.',take:'Lấy ký hiệu đầu hàng đợi.',duplicate:'Ký hiệu này đã được xử lý, không giảm các bộ đếm lần nữa.',infer:'Đánh dấu ký hiệu đã xử lý. Nó là hệ quả từ những tri thức đã có.',count:'Một tiền đề của luật đã được xử lý. Giảm bộ đếm đúng một lần.',fire:'Mọi tiền đề của luật đã được xử lý. Đưa kết luận vào hàng đợi.',goal:'Chọn mục tiêu bên trái trong danh sách.',resolve:'Khớp mục tiêu với đầu luật. Thay mục tiêu đó bằng thân luật và giữ các mục tiêu còn lại.',loop:'Danh sách mục tiêu này đã xuất hiện trên nhánh hiện tại. Cắt nhánh vòng lặp rồi thử luật khác.',backtrack:'Nhánh vừa thử không chứng minh được mục tiêu. Quay lại thử luật khác.',deadend:'Không còn luật phù hợp trên nhánh này. Đây là thất bại của nhánh.',success:'Đã chứng minh được truy vấn.',unknown:'Đã kết thúc tìm kiếm mà chưa suy ra truy vấn. Không được kết luận phủ định của truy vấn là đúng.',budget:'Chạm giới hạn 1.000 thao tác của bộ xem. Chưa kết luận chứng minh được hay không.'}
function apply(){try{const e=JSON.parse(input.value);validateHorn(e);custom.value=e;error.value='';step.value=0}catch(e){error.value=e.message}}
</script>
<template><figure class="lab prop-inference" aria-label="Truy vết suy luận tiến và hợp giải SLD"><div class="infer-settings"><label>Phương pháp<select v-model="mode"><option value="forward">Suy luận tiến</option><option value="sld">Hợp giải SLD</option></select></label><label>Ví dụ<select v-model="preset"><option v-for="e in hornExamples" :key="e.id" :value="e.id">{{ e.title }}</option></select></label></div><p>Sự thực: {{ validated.facts.join(', ')||'Không có' }}. Truy vấn nguyên tử: {{ validated.query }}. Luật theo thứ tự trong danh sách. SLD chọn mục tiêu trái nhất và thử luật theo thứ tự, sau đó thử sự thực. Mục tiêu lặp được gộp theo tính lũy đẳng của phép hội.</p><SimulationControls v-model="step" :max="frames.length-1" :reset-key="resetKey"/><p class="infer-status" role="status">{{ status[state.phase] }}<span v-if="state.current"> Ký hiệu {{ state.current }}.</span><span v-if="state.rule"> Luật {{ state.rule }}.</span></p><div class="infer-panels"><section><h4>Các luật và tiền đề</h4><ol class="infer-rules"><li v-for="(r,i) in validated.rules" :key="r.id" :class="{active:state.rule===r.id}"><strong>{{ r.id }}</strong><span>{{ r.body.length?r.body.join(' ∧ '):'⊤' }} ⇒ {{ r.head }}</span><span v-if="mode==='forward'">Còn chờ {{ state.count[i] }} tiền đề</span></li></ol><p v-for="(f,i) in validated.facts" :key="f">f{{ i+1 }}: {{ f }}.</p></section><section v-if="mode==='forward'" class="infer-working"><h4>Hàng đợi và kết quả</h4><p>Agenda: {{ state.agenda.join(' → ')||'Rỗng' }}.</p><p>Đã xử lý: {{ state.inferred.join(', ')||'Chưa có' }}.</p><p>Bộ đếm 0 chỉ có nghĩa mọi tiền đề đã được xử lý. inferred chưa đánh dấu không có nghĩa ký hiệu sai.</p></section><section v-else class="infer-working"><h4>Danh sách mục tiêu và ngăn xếp</h4><p>Mục tiêu: {{ state.goals.length?state.goals.join(' ∧ '):'[] · Không còn mục tiêu' }}.</p><ol><li v-for="(f,i) in state.stack" :key="i">{{ f.selected }} qua {{ f.rule }} · Trước đó [{{ f.goals }}]</li></ol><p>Danh sách mục tiêu là phép hội cần chứng minh. Clause phản chứng tương ứng là tuyển các phủ định của những mục tiêu này.</p></section></div><PropositionalCode :code="mode==='forward'?forwardCode:sldCode" :phase="state.phase"/><details class="infer-edit"><summary>Nhập sự thực, luật và truy vấn</summary><p>JSON gồm facts, rules, query. Mỗi luật có body là mảng tiền đề và head là một ký hiệu. Body rỗng biểu diễn sự thực. Tối đa 12 ký hiệu, 16 luật. Không nhận phủ định hay đầu luật tuyển trong bộ suy luận definite.</p><label>Dữ liệu<textarea v-model="input" rows="9" spellcheck="false"/></label><button type="button" @click="apply">Áp dụng</button><p v-if="error" role="alert">{{ error }}</p></details><details class="lab-tasks"><summary>Dự đoán trước khi chạy</summary><ol><li>Vì sao luật L ∧ M ⇒ P chưa kích hoạt khi mới có L?</li><li>Tại sao ký hiệu L có thể vào hàng đợi lần nữa mà không được giảm bộ đếm lần nữa?</li><li>Chuyển sang SLD rồi chọn ví dụ nhánh vòng lặp đứng trước lời giải. Quan sát quay lui.</li><li>Thử chu trình không có sự thực. Vì sao nó không tự tạo ra Q?</li></ol></details></figure></template>
<style scoped>
.prop-inference{min-width:0}.infer-settings{display:grid;grid-template-columns:1fr 1fr;gap:12px}.prop-inference label{display:grid;gap:6px}.prop-inference :is(button,select,textarea){min-height:44px;padding:8px;max-width:100%;box-sizing:border-box;border:1px solid var(--control);border-radius:var(--radius);background:var(--paper);color:var(--ink);font:var(--fs-small)/1.6 var(--font-ui)}.prop-inference :is(select,textarea){width:100%}.prop-inference :is(button,select,textarea):focus-visible{outline:3px solid var(--tim);outline-offset:3px}.prop-inference :is(p,li,summary){font:var(--fs-small)/1.7 var(--font-ui);overflow-wrap:anywhere}.prop-inference h4{font:600 var(--fs-ui)/1.6 var(--font-ui)}.infer-status{padding:12px;background:var(--tim-soft);border-left:3px solid var(--tim)}.infer-panels{display:grid;grid-template-columns:1fr 1fr;gap:16px}.infer-panels section{min-width:0;border:1px solid var(--rule);border-radius:var(--radius);padding:12px}.infer-rules{list-style:none;margin:0;padding:0!important;display:grid;gap:8px}.infer-rules li{display:grid;gap:4px;padding:8px;border:1px solid var(--rule);border-radius:var(--radius)}.infer-rules .active{border-color:var(--tim);background:var(--tim-soft)}.prop-inference details{margin-top:16px}.prop-inference summary{cursor:pointer;min-height:44px}.infer-edit textarea{font:12px/1.7 var(--font-code);margin:8px 0}.prop-inference button{cursor:pointer}@media(max-width:700px){.infer-settings,.infer-panels{grid-template-columns:minmax(0,1fr)}.prop-inference{padding:12px}}
</style>
